constexpr auto operator==(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(lhs.get() == rhs.get()))
    -> decltype(lhs.get() == rhs.get());

template <class T, class U>
constexpr auto operator!=(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(lhs.get() != rhs.get()))
    -> decltype(lhs.get() != rhs.get());

template <class T, class U>
constexpr auto operator<(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(std::less<>{}(lhs.get(), rhs.get())))
    -> decltype(std::less<>{}(lhs.get(), rhs.get()));

template <class T, class U>
constexpr auto operator<=(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(std::less_equal<>{}(lhs.get(), rhs.get())))
    -> decltype(std::less_equal<>{}(lhs.get(), rhs.get()));

template <class T, class U>
constexpr auto operator>(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(std::greater<>{}(lhs.get(), rhs.get())))
    -> decltype(std::greater<>{}(lhs.get(), rhs.get()));

template <class T, class U>
constexpr auto operator>=(const gsl::not_null<T>& lhs, const gsl::not_null<U>& rhs) noexcept(noexcept(std::greater_equal<>{}(lhs.get(), rhs.get())))
    -> decltype(std::greater_equal<>{}(lhs.get(), rhs.get()));

