// Use two disjoint buffers to satisfy the non-overlap requirement and ensure
// destination has sufficient capacity for the copy operation.
std::string src = FUZZ_PARAM_STR();
// Choose a copy count within source size bounds to keep [first, last) valid
std::size_t src_len = src.size();
std::size_t max_copy = src_len; // FUZZ_PARAM_STR guarantees size >= 1
std::size_t count = max_copy;

// Prepare a destination vector with at least 'count' writable elements
std::vector<char> dst(count + 8u, 0); // a little slack to avoid boundary issues

// Establish non-overlapping ranges using raw pointers
const char* first = src.data();
const char* last  = src.data() + count;
char* d_first = dst.data();

// Perform the copy
char* d_last = std::copy(first, last, d_first);

// Validate the returned end iterator points exactly after the last written element
FUZZ_ASSERT(d_last == d_first + count, "std::copy must return end of destination range");

// Additional sanity: verify copied bytes match
for (std::size_t i = 0; i < count; ++i) {
    if (dst[i] != src[i]) { FUZZ_BAIL(); }
}

// Validation: This stub ensures valid, non-overlapping ranges and sufficient dst capacity, and asserts the return iterator and byte equality.

// Exercise several type pairs; narrow_cast is noexcept and unchecked.
int i32 = *FUZZ_PARAM(int);
unsigned int u32 = *FUZZ_PARAM(unsigned int);
long long i64 = *FUZZ_PARAM(long long);
double d = *FUZZ_PARAM(double);

// A few representative conversions
volatile unsigned char uc1 = gsl::narrow_cast<unsigned char>(i32);
volatile int i1 = gsl::narrow_cast<int>(d);
volatile short s1 = gsl::narrow_cast<short>(i64);
volatile unsigned int u1 = gsl::narrow_cast<unsigned int>(i64);
volatile long long l1 = gsl::narrow_cast<long long>(u32);

// Touch results to avoid optimization removing calls
(void)uc1; (void)i1; (void)s1; (void)u1; (void)l1;

// Validation: Calls cover multiple instantiations; no runtime checks or exceptions are expected by API.

// Create a guard that flips a flag on scope exit; ensure it runs exactly once.
bool ran = false;
{
    auto guard = gsl::finally([&ran]() noexcept { ran = true; });
    // do some work; ensure no throws from the lambda to avoid terminate in dtor
}
FUZZ_ASSERT(ran, "gsl::finally must invoke the callable at scope exit");

// Also validate move semantics: after move, only the moved-to guard should run once.
int count = 0;
{
    auto g1 = gsl::finally([&count]() noexcept { ++count; });
    auto g2 = std::move(g1); // move the guard; g1 is released, g2 owns the callable
}
FUZZ_ASSERT(count == 1, "Moved gsl::finally guard should invoke callable exactly once");

// Validation: The stub ensures non-throwing cleanup actions and asserts single, deterministic invocation, including move behavior.

// Exercise checked narrowing conversions; handle potential exceptions gracefully.
int i32 = *FUZZ_PARAM(int);
long long i64 = *FUZZ_PARAM(long long);
unsigned long long u64 = *FUZZ_PARAM(unsigned long long);
double d = *FUZZ_PARAM(double);

try {
    volatile unsigned char uc = gsl::narrow<unsigned char>(i32);
    (void)uc;
} catch (const std::exception&) {
    // Expected for out-of-range values; continue
}

try {
    volatile int i_from_ll = gsl::narrow<int>(i64);
    (void)i_from_ll;
} catch (const std::exception&) {
}

try {
    volatile int i_from_u64 = gsl::narrow<int>(u64);
    (void)i_from_u64;
} catch (const std::exception&) {
}

try {
    volatile int i_from_d = gsl::narrow<int>(d);
    (void)i_from_d;
} catch (const std::exception&) {
}

// Validation: The stub covers success/failure paths and properly catches exceptions that signal invalid narrowing.

// Create a dynamic span over initialized data and obtain its iterator
std::string backing = FUZZ_PARAM_STR();
const std::size_t n = backing.size();
std::vector<unsigned char> buf(n, 0);
if (n > 0) { std::memcpy(buf.data(), backing.data(), n); }

// Construct a span over the buffer
gsl::span<unsigned char> s(buf.data(), buf.size());

// Take a valid iterator and convert to raw pointer via pointer_traits::to_address
auto it = s.begin();
unsigned char* raw = std::pointer_traits<decltype(it)>::to_address(it);

// Validate that the returned address matches s.data() (property of span_iterator)
FUZZ_ASSERT(raw == s.data(), "to_address must return underlying span::data()");

// Validation: Exercises pointer extraction on a valid iterator and asserts returned pointer correctness.

// Default-construct a dynamic-extent span
// This constructor only participates when Extent == 0 or dynamic_extent; we pick dynamic_extent via gsl::span<int>
gsl::span<int> s;
// Validate postconditions: empty span has size()==0 and data()==nullptr
FUZZ_ASSERT(s.size() == 0, "default-constructed span must be empty");
FUZZ_ASSERT(s.data() == nullptr, "default-constructed span must have nullptr data");

// Validation: Ensures SFINAE-friendly default ctor is callable and enforces empty invariants.

// Prepare source and destination spans of identical type
auto bytes = FUZZ_PARAM_STR();
std::vector<int> src_vec(bytes.size() / sizeof(int) + 1, 0);
if (!src_vec.empty()) {
    // Fill with some data to avoid uninitialized reads
    std::memcpy(reinterpret_cast<unsigned char*>(src_vec.data()), bytes.data(), std::min(bytes.size(), src_vec.size()*sizeof(int)));
}

gsl::span<int> src(src_vec.data(), src_vec.size());
gsl::span<int> dst; // default-constructed empty span of same type

// Copy-assign; noexcept in API
dst = src;

// Validate that pointer and size were copied
FUZZ_ASSERT(dst.size() == src.size(), "copy-assigned span must copy size");
FUZZ_ASSERT(dst.data() == src.data(), "copy-assigned span must alias same data pointer");

// Validation: Exercises copy assignment and asserts aliasing semantics.

// Build a span over initialized bytes
std::string backing = FUZZ_PARAM_STR();
std::vector<unsigned char> buf(backing.size(), 0);
if (!buf.empty()) { std::memcpy(buf.data(), backing.data(), buf.size()); }

gsl::span<unsigned char> s(buf.data(), buf.size());

// Choose a compile-time Count via a runtime branch
switch ((*FUZZ_PARAM(unsigned int)) % 3) {
    case 0: {
        constexpr std::size_t Count = 0;
        auto sub = s.first<Count>();
        FUZZ_ASSERT(sub.size() == Count, "first<0> must be empty");
        FUZZ_ASSERT(sub.data() == s.data(), "first<0> data must equal original data");
        break;
    }
    case 1: {
        constexpr std::size_t Count = 1;
        if (s.size() < Count) { FUZZ_BAIL(); }
        auto sub = s.first<Count>();
        FUZZ_ASSERT(sub.size() == Count, "first<1> must have size 1");
        FUZZ_ASSERT(sub.data() == s.data(), "first<1> must start at original data");
        break;
    }
    default: {
        constexpr std::size_t Count = 2;
        if (s.size() < Count) { FUZZ_BAIL(); }
        auto sub = s.first<Count>();
        FUZZ_ASSERT(sub.size() == Count, "first<2> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data(), "first<2> must start at original data");
        break;
    }
}

// Validation: Guards runtime precondition Count <= size() and checks returned view properties.

// Build a span over initialized bytes
std::string backing = FUZZ_PARAM_STR();
std::vector<unsigned char> buf(backing.size(), 0);
if (!buf.empty()) { std::memcpy(buf.data(), backing.data(), buf.size()); }

gsl::span<unsigned char> s(buf.data(), buf.size());

// Choose a compile-time Count via a runtime branch
switch ((*FUZZ_PARAM(unsigned int)) % 3) {
    case 0: {
        constexpr std::size_t Count = 0;
        auto sub = s.last<Count>();
        FUZZ_ASSERT(sub.size() == Count, "last<0> must be empty");
        FUZZ_ASSERT(sub.data() == s.data() + s.size(), "last<0> data equals end() pointer");
        break;
    }
    case 1: {
        constexpr std::size_t Count = 1;
        if (s.size() < Count) { FUZZ_BAIL(); }
        auto sub = s.last<Count>();
        FUZZ_ASSERT(sub.size() == Count, "last<1> must have size 1");
        FUZZ_ASSERT(sub.data() == s.data() + (s.size() - Count), "last<1> must start at last element");
        break;
    }
    default: {
        constexpr std::size_t Count = 2;
        if (s.size() < Count) { FUZZ_BAIL(); }
        auto sub = s.last<Count>();
        FUZZ_ASSERT(sub.size() == Count, "last<2> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data() + (s.size() - Count), "last<2> start pointer mismatch");
        break;
    }
}

// Validation: Enforces Count <= size() and verifies correct tail view.

// Build a span over initialized ints
std::string bytes = FUZZ_PARAM_STR();
std::vector<int> vec(bytes.size() / sizeof(int) + 2, 0);
if (!vec.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(vec.data()), bytes.data(), std::min(bytes.size(), vec.size()*sizeof(int)));
}

gsl::span<int> s(vec.data(), vec.size());

// Select among several compile-time Offset/Count combinations
switch ((*FUZZ_PARAM(unsigned int)) % 4) {
    case 0: {
        constexpr std::size_t Offset = 0;
        constexpr std::size_t Count  = gsl::dynamic_extent;
        if (s.size() < Offset) { FUZZ_BAIL(); }
        auto sub = s.subspan<Offset, Count>();
        FUZZ_ASSERT(sub.size() == s.size() - Offset, "subspan<0,dyn> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data() + Offset, "subspan<0,dyn> start mismatch");
        break;
    }
    case 1: {
        constexpr std::size_t Offset = 1;
        constexpr std::size_t Count  = gsl::dynamic_extent;
        if (s.size() < Offset) { FUZZ_BAIL(); }
        auto sub = s.subspan<Offset, Count>();
        FUZZ_ASSERT(sub.size() == s.size() - Offset, "subspan<1,dyn> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data() + Offset, "subspan<1,dyn> start mismatch");
        break;
    }
    case 2: {
        constexpr std::size_t Offset = 0;
        constexpr std::size_t Count  = 1;
        if (s.size() < Offset + Count) { FUZZ_BAIL(); }
        auto sub = s.subspan<Offset, Count>();
        FUZZ_ASSERT(sub.size() == Count, "subspan<0,1> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data() + Offset, "subspan<0,1> start mismatch");
        break;
    }
    default: {
        constexpr std::size_t Offset = 1;
        constexpr std::size_t Count  = 1;
        if (s.size() < Offset + Count) { FUZZ_BAIL(); }
        auto sub = s.subspan<Offset, Count>();
        FUZZ_ASSERT(sub.size() == Count, "subspan<1,1> size mismatch");
        FUZZ_ASSERT(sub.data() == s.data() + Offset, "subspan<1,1> start mismatch");
        break;
    }
}

// Validation: Covers both dynamic and fixed Count cases with runtime precondition checks.

// Construct a span and validate size reports element count
std::string backing = FUZZ_PARAM_STR();
std::vector<unsigned short> buf(backing.size() / sizeof(unsigned short), 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(unsigned short)));
}

gsl::span<unsigned short> s(buf.data(), buf.size());
FUZZ_ASSERT(s.size() == buf.size(), "span::size must equal underlying container size");

// Validation: Simple size equality check.

// Construct a span and validate size_bytes == size()*sizeof(T)
