std::vector<std::uint32_t> buf(backing.size() / sizeof(std::uint32_t) + 1, 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(std::uint32_t)));
}

gsl::span<std::uint32_t> s(buf.data(), buf.size());
FUZZ_ASSERT(s.size_bytes() == s.size() * sizeof(std::uint32_t), "size_bytes must equal size()*sizeof(T)");

// Validation: Confirms byte size computation matches expectation.

// Construct a span and check empty() coherency
std::string backing = FUZZ_PARAM_STR();
std::vector<char> buf(backing.begin(), backing.end());

gsl::span<char> s(buf.data(), buf.size());
FUZZ_ASSERT(s.empty() == (s.size() == 0), "empty() must be equivalent to size()==0");

