std::vector<unsigned char> buf(backing.begin(), backing.end());

gsl::span<unsigned char> s(buf.data(), buf.size());
if (s.size() == 0) { FUZZ_BAIL(); }
(void)s.front();

// Validation: Enforces non-empty precondition and calls front().

