std::vector<unsigned char> buf(backing.begin(), backing.end());

gsl::span<unsigned char> s(buf.data(), buf.size());
if (s.size() == 0) { FUZZ_BAIL(); }
(void)s.back();

// Validation: Enforces non-empty precondition and calls back().

// Construct a span and validate data() pointer consistency
std::string backing = FUZZ_PARAM_STR();
std::vector<std::byte> buf(backing.size(), std::byte{0});
if (!buf.empty()) { std::memcpy(buf.data(), backing.data(), buf.size()); }

gsl::span<std::byte> s(buf.data(), buf.size());
if (s.size() == 0) {
    FUZZ_ASSERT(s.data() == nullptr || s.data() == buf.data(), "empty span may return nullptr or valid pointer depending on implementation");
