// Validation: Checks data() aligns with contiguous storage.

// Construct a span and obtain begin iterator
std::string backing = FUZZ_PARAM_STR();
std::vector<int> buf(backing.size() / sizeof(int) + 1, 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(int)));
}

gsl::span<int> s(buf.data(), buf.size());
auto b = s.begin();
// Validate that to_address(begin) equals data()
int* pb = std::pointer_traits<decltype(b)>::to_address(b);
FUZZ_ASSERT(pb == s.data(), "begin() must point to data()");

// Validation: Confirms iterator points to first element.

// Construct a span and obtain end iterator
std::string backing = FUZZ_PARAM_STR();
std::vector<int> buf(backing.size() / sizeof(int) + 1, 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(int)));
}

gsl::span<int> s(buf.data(), buf.size());
auto e = s.end();
int* pe = std::pointer_traits<decltype(e)>::to_address(e);
FUZZ_ASSERT(pe == s.data() + s.size(), "end() must equal data()+size()");

// Validation: Confirms end iterator equals one-past-last.

// Construct a span and obtain rbegin
std::string backing = FUZZ_PARAM_STR();
std::vector<int> buf(backing.size() / sizeof(int) + 1, 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(int)));
}

gsl::span<int> s(buf.data(), buf.size());
auto rb = s.rbegin();
// For non-empty, base().base() should equal end(); for empty, also valid
if (s.size() > 0) {
    int* pend = std::pointer_traits<decltype(s.end())>::to_address(s.end());
    int* prb  = std::pointer_traits<decltype(rb.base())>::to_address(rb.base());
    FUZZ_ASSERT(prb == pend, "rbegin().base() must equal end() for forward iterator base");
}

// Validation: Touches reverse-iterator construction and basic relation.

// Construct a span and obtain rend
std::string backing = FUZZ_PARAM_STR();
std::vector<int> buf(backing.size() / sizeof(int) + 1, 0);
if (!buf.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(buf.data()), backing.data(), std::min(backing.size(), buf.size()*sizeof(int)));
}

gsl::span<int> s(buf.data(), buf.size());
auto re = s.rend();
if (s.size() > 0) {
    int* pbegin = std::pointer_traits<decltype(s.begin())>::to_address(s.begin());
    int* pre    = std::pointer_traits<decltype(re.base())>::to_address(re.base());
    FUZZ_ASSERT(pre == pbegin, "rend().base() must equal begin() for forward iterator base");
}

// Validation: Touches reverse end iterator and relation to begin().

// Build a span over a trivially copyable type and view as const bytes
std::string backing = FUZZ_PARAM_STR();
std::vector<std::uint32_t> vec(backing.size() / sizeof(std::uint32_t) + 1, 0);
if (!vec.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(vec.data()), backing.data(), std::min(backing.size(), vec.size()*sizeof(std::uint32_t)));
}

gsl::span<std::uint32_t> s(vec.data(), vec.size());
auto b = gsl::as_bytes(s);
// Validate size in bytes and pointer aliasing
FUZZ_ASSERT(b.size() == s.size() * sizeof(std::uint32_t), "as_bytes size must match");
if (s.size() > 0) {
    FUZZ_ASSERT(b.data() == reinterpret_cast<const gsl::impl::byte*>(s.data()), "as_bytes data must alias object representation");
}

// Validation: Ensures const byte view length and aliasing are correct.

// Build a span over non-const elements and view as writable bytes
std::string backing = FUZZ_PARAM_STR();
std::vector<std::uint16_t> vec(backing.size() / sizeof(std::uint16_t) + 1, 0);
if (!vec.empty()) {
    std::memcpy(reinterpret_cast<unsigned char*>(vec.data()), backing.data(), std::min(backing.size(), vec.size()*sizeof(std::uint16_t)));
}

gsl::span<std::uint16_t> s(vec.data(), vec.size());
auto wb = gsl::as_writable_bytes(s);
FUZZ_ASSERT(wb.size() == s.size() * sizeof(std::uint16_t), "as_writable_bytes size must match");
// If not empty, mutate one byte and observe underlying storage changes in object representation
if (wb.size() > 0) {
    gsl::impl::byte* p = wb.data();
    gsl::impl::byte old = *p;
    // Toggle lowest bit
    *p = gsl::impl::byte(static_cast<unsigned char>(static_cast<unsigned char>(old) ^ 0x1));
    // The first byte of the underlying element must now differ
    const unsigned char* raw = reinterpret_cast<const unsigned char*>(s.data());
    FUZZ_ASSERT(static_cast<unsigned char>(*p) == (raw[0] ^ 0x1), "mutation through writable bytes must reflect in underlying storage");
}

// Validation: Confirms writable byte view size and that writes affect underlying elements.

// Construct two contiguous buffers with small bounded sizes and fill them from fuzz data.
unsigned int raw_sz1 = *FUZZ_PARAM(unsigned int);
unsigned int raw_sz2 = *FUZZ_PARAM(unsigned int);
std::size_t sz1 = static_cast<std::size_t>(raw_sz1 % 64);
std::size_t sz2 = static_cast<std::size_t>(raw_sz2 % 64);
std::string src1 = FUZZ_PARAM_STR();
