import random
import struct
from typing import List

# This generator targets stubs that primarily consume FUZZ_PARAM_STR() and a few FUZZ_PARAM(unsigned int).
# FUZZ_PARAM_STR() should yield arbitrary binary of varying sizes, sometimes used to fill vectors of
# various element sizes (char/byte, uint16_t, uint32_t, int) and sometimes copied into two disjoint ranges.
# Our goal is to provide initial buffers that are valid, interesting, and exercise edge cases like:
# - empty or very small strings (to test size==0 paths and Count==0 specializations)
# - size 1, 2 for first/last<1,2>
# - sizes aligning/misaligned to 2 and 4 for uint16_t/uint32_t packing/memcpy boundaries
# - repeated patterns and incremental patterns for copy and equality checks
# - random data to increase coverage
# Additionally, for not_null pointer operator stubs, the harness itself supplies the not_null pointers;
# our input is only used by the span and copy related stubs, so any arbitrary binary buffers are acceptable.

_MAX = 4096

# Pattern builders

def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n

def _pattern_ones(n: int) -> bytes:
    return b"\xFF" * n

def _pattern_increment(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_alt(n: int, a: int = 0xAA, b: int = 0x55) -> bytes:
    seq = bytearray(n)
    for i in range(n):
        seq[i] = a if (i % 2 == 0) else b
    return bytes(seq)

def _pattern_words16(n: int, endian: str) -> bytes:
    # produce a sequence of 16-bit words with varying values
    out = bytearray()
    val = 0
    while len(out) < n:
        word = val & 0xFFFF
        if endian == 'le':
            out += struct.pack('<H', word)
        else:
            out += struct.pack('>H', word)
        val = (val + 0x1111) & 0xFFFF
    return bytes(out[:n])

def _pattern_words32(n: int, endian: str) -> bytes:
    out = bytearray()
    val = 0
    while len(out) < n:
        dword = (0x01020304 + val) & 0xFFFFFFFF
        if endian == 'le':
            out += struct.pack('<I', dword)
        else:
            out += struct.pack('>I', dword)
        val = (val + 0x11111111) & 0xFFFFFFFF
    return bytes(out[:n])

def _pattern_repeat_block(n: int, block: bytes) -> bytes:
    if not block:
        return b""
    reps = (n + len(block) - 1) // len(block)
    return (block * reps)[:n]

# Size selection helpers tailored to the stubs

def _choose_sizes(rng: random.Random) -> List[int]:
    # Curate sizes that are particularly interesting for the spans used in stubs.
    base_sizes = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64]
    # Add a few random sizes including misaligned to 2 and 4, and some bigger but bounded
    for _ in range(6):
        base_sizes.append(rng.randint(5, 96))
    # Ensure we do not exceed maximum total when combined; per buffer limit is enforced later.
    return base_sizes


def _build_payload(rng: random.Random, size: int) -> bytes:
    # Select one of multiple pattern families to increase coverage
    choice = rng.randint(0, 8)
    if choice == 0:
        return _pattern_zero(size)
    elif choice == 1:
        return _pattern_ones(size)
    elif choice == 2:
        return _pattern_increment(size, start=rng.randint(0, 255))
    elif choice == 3:
        return _pattern_alt(size)
    elif choice == 4:
        # 16-bit words little-endian to exercise uint16_t packing
        return _pattern_words16(size, 'le')
    elif choice == 5:
        # 16-bit words big-endian
        return _pattern_words16(size, 'be')
    elif choice == 6:
        # 32-bit words little-endian to exercise uint32_t packing and size_bytes math
        return _pattern_words32(size, 'le')
    elif choice == 7:
        return _pattern_words32(size, 'be')
    else:
        # Repeated block composed of small interesting bytes
        block = bytes([0x00, 0xFF, 0x7F, 0x80, 0x01, 0xFE])
        return _pattern_repeat_block(size, block)


def _assemble_buffers(rng: random.Random) -> bytes:
    # We may concatenate multiple FUZZ_PARAM_STR payloads into one input buffer; the harness will split
    # across calls internally. To help multiple stubs in one run, provide a series of length-prefixed blobs.
    # Format: [count:u8] then count times { len:u16_le, data }
    sizes = _choose_sizes(rng)

    # Limit total to _MAX; select subset sizes and build corresponding payloads
    entries = []
    total = 1  # reserve for count byte
    rng.shuffle(sizes)
    for sz in sizes:
        # Also diversify by sometimes scaling size a bit
        scale_choice = rng.randint(0, 4)
        if scale_choice == 1:
            sz = sz * 2
        elif scale_choice == 2:
            sz = sz * 4
        # Keep within reasonable per-payload bound and overall max
        sz = max(0, min(sz, 256))
        if total + 2 + sz > _MAX:
            continue
        payload = _build_payload(rng, sz)
        entries.append(payload)
        total += 2 + len(payload)
        # Ensure at least a few entries but not too many
        if len(entries) >= 12 and total > _MAX // 2:
            break

    # Ensure we have at least one non-empty and one small entry to hit edge cases
    if not entries:
        entries = [b"", b"\x00", b"A"]
    else:
        have_empty = any(len(e) == 0 for e in entries)
        if not have_empty and total + 2 <= _MAX:
            entries.insert(0, b"")
        have_small1 = any(len(e) == 1 for e in entries)
        if not have_small1 and total + 2 + 1 <= _MAX:
            entries.insert(1, b"X")
        have_small2 = any(len(e) == 2 for e in entries)
        if not have_small2 and total + 2 + 2 <= _MAX:
            entries.insert(2, b"YZ")

    # Build the length-prefixed container
    out = bytearray()
    out.append(len(entries) & 0xFF)
    for blob in entries:
        out += struct.pack('<H', len(blob))
        out += blob

    # Add a small trailer with some 32-bit integers to serve as FUZZ_PARAM(unsigned int) entropy source
    # even if the harness consumes from the same stream. We add 4 or 8 bytes.
    trailer_count = rng.choice([0, 4, 8])
    if len(out) + trailer_count <= _MAX:
        # mix of fixed interesting and random values
        ints = []
        if trailer_count >= 4:
            ints.append(0)
        if trailer_count >= 8:
            ints.append(0xFFFFFFFF)
        while len(ints) * 4 < trailer_count:
            ints.append(rng.getrandbits(32))
        for v in ints:
            out += struct.pack('<I', v)

    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return _assemble_buffers(rng)
